D=/opt/trading-bot/genetic; tail -1 $D/run_feat_short.log | cut -c1-200; python3 -c "
import json
for d in (\"feat\",\"feat_short\"):
    try: r=json.load(open(\"/opt/trading-bot/genetic/%s/results.json\"%d))
    except Exception as e: print(d,e); continue
    print(d, r[\"meta\"][\"status\"], r[\"verdict\"])
    for n,x in r[\"runs\"].items():
        t=x.get(\"top\")
        if t: print(\" \",n,\"evals\",x[\"evals\"],\"best\",round(x[\"best_fit\"],3),\"pass\",x[\"npass\"],\"maxHO\",round(max(a[\"ho\"][\"tm\"] for a in t),3),\"maxUN\",round(max(a[\"un\"][\"tm\"] for a in t),3))
    for a in r[\"runs\"][\"real\"].get(\"top\",[])[:3]: print(\"  \",round(a[\"fit\"],3),[b[\"n\"] for b in a[\"blocks\"]],a[\"ho\"][\"n\"],round(a[\"ho\"][\"tm\"],3),a[\"un\"][\"n\"],round(a[\"un\"][\"tm\"],3),a[\"text\"])
"
